/**
 * Renders the files `relkit deploy init railway` writes: `railway.json`, a source Dockerfile with
 * its context allowlist, and a GitHub Actions workflow that deploys on push. Pure renderers; the
 * command writes them and never calls Railway.
 */
import type { RuntimeName } from "relkit/runtime";
import { BUN_IMAGE, NODE_IMAGE, productionPolicy } from "./build-container.js";

/** Railway CLI release the generated workflow runs. */
export const RAILWAY_CLI_VERSION = "5.71.0";

/** One generated file, relative to the project root. */
export interface DeployInitFile {
  readonly path: string;
  readonly content: string;
}

/**
 * Renders every Railway file for the selected server runtime.
 * @param runtime - Runtime the production server runs on.
 * @returns Files in write order.
 */
export function railwayFiles(runtime: RuntimeName): readonly DeployInitFile[] {
  return [
    { path: "railway.json", content: railwayConfig() },
    { path: "Dockerfile", content: railwayDockerfile(runtime) },
    { path: ".dockerignore", content: railwayDockerignore() },
    { path: ".github/workflows/railway-deploy.yml", content: railwayWorkflow() },
  ];
}

/**
 * Renders the service configuration. Railway builds the Dockerfile, gates each deploy on
 * `/healthz` (ready once every provider is ready) and allows the server's 60-second drain.
 * @returns `railway.json` source.
 */
export function railwayConfig(): string {
  return `${JSON.stringify(
    {
      $schema: "https://railway.com/railway.schema.json",
      build: { builder: "DOCKERFILE", dockerfilePath: "Dockerfile" },
      deploy: {
        healthcheckPath: "/healthz",
        healthcheckTimeout: 120,
        drainingSeconds: 70,
        restartPolicyType: "ON_FAILURE",
        restartPolicyMaxRetries: 5,
      },
    },
    null,
    2,
  )}\n`;
}

/**
 * Renders the source Dockerfile: the build stage runs `relkit build` from the lockfile, the
 * dependency stage installs the lockfile's production dependencies, and the final stage runs the
 * built server as the runtime's non-root user with durable state kept outside the container.
 * @param runtime - Runtime the production server runs on.
 * @returns Dockerfile source.
 */
export function railwayDockerfile(runtime: RuntimeName): string {
  const user = runtime === "node" ? "node" : "bun";
  const command =
    runtime === "node"
      ? '["node", "server/index.js"]'
      : '["bun", "run", "--no-env-file", "server/index.js"]';
  return `# Generated by \`relkit deploy init railway\`. Builds the application from source.
FROM ${BUN_IMAGE} AS build
WORKDIR /src
COPY . .
RUN bun install --frozen-lockfile
RUN ./node_modules/.bin/relkit build --runtime ${runtime}

FROM ${BUN_IMAGE} AS dependencies
WORKDIR /src
COPY . .
RUN bun install --frozen-lockfile --production
RUN mkdir -p node_modules

FROM ${runtime === "node" ? NODE_IMAGE : BUN_IMAGE}
ARG SOURCE_DATE_EPOCH=0
WORKDIR /app
COPY --from=build /src/.relkit/build/ ./
COPY --from=dependencies /src/node_modules ./node_modules
${productionPolicy(user, runtime)}CMD ${command}
`;
}

/**
 * Renders the context allowlist inverse: local installs, build output, state and secrets stay out.
 * @returns `.dockerignore` source.
 */
export function railwayDockerignore(): string {
  return `node_modules
.relkit
.env
.env.*
!.env.example
.git
.github
coverage
*.log
`;
}

/**
 * Renders the workflow that checks the project and deploys it with the Railway CLI on push to
 * `main`. It needs the `RAILWAY_TOKEN` secret (a project token) and the `RAILWAY_SERVICE`
 * variable; `RAILWAY_WORKER_SERVICE`, when set, deploys the same source to the worker service.
 * @returns Workflow YAML.
 */
export function railwayWorkflow(): string {
  return `# Generated by \`relkit deploy init railway\`. Deploys to Railway on every push to main.
# Secrets: RAILWAY_TOKEN (a Railway project token). Variables: RAILWAY_SERVICE, and optionally
# RAILWAY_WORKER_SERVICE for a separate worker service built from the same source.
name: Deploy to Railway

on:
  push:
    branches: [main]
  workflow_dispatch:

concurrency:
  group: railway-deploy
  cancel-in-progress: false

permissions:
  contents: read

jobs:
  deploy:
    runs-on: ubuntu-latest
    env:
      RAILWAY_TOKEN: \${{ secrets.RAILWAY_TOKEN }}
    steps:
      - uses: actions/checkout@v4
      - uses: oven-sh/setup-bun@v2
        with:
          bun-version: 1.3.10
      - run: bun install --frozen-lockfile
      - run: bun run check
      - run: bun run typecheck
      - run: bun run test
      - name: Deploy the web service
        run: bunx @railway/cli@${RAILWAY_CLI_VERSION} up --ci --service "\${{ vars.RAILWAY_SERVICE }}"
      - name: Deploy the worker service
        if: \${{ vars.RAILWAY_WORKER_SERVICE != '' }}
        run: bunx @railway/cli@${RAILWAY_CLI_VERSION} up --ci --service "\${{ vars.RAILWAY_WORKER_SERVICE }}"
`;
}
